            EXPECT_THROW(admit(invalid), std::invalid_argument);
            EXPECT_FALSE(physics.hasActorRagdoll(ptr));
            EXPECT_FALSE(capsule->isCollisionSuspended());
            ASSERT_NE(capsule->getCollisionObject()->getBroadphaseHandle(), nullptr);
            admit(graph);
