            EXPECT_TRUE(capsule->isCollisionSuspended());
            EXPECT_EQ(capsule->getCollisionObject()->getBroadphaseHandle(), nullptr);
            EXPECT_EQ(physics.actorRagdollOwners(), std::vector<MWWorld::Ptr>{ptr});
