            EXPECT_EQ(physics.captureActorRagdollSnapshot(ptr, base, path.value()), keyModeSnapshot);
            ASSERT_TRUE(keyModeSnapshot.mNativeBlends); ASSERT_EQ(keyModeSnapshot.mNativeBlends->size(), 1u);
