            EXPECT_EQ(physics.captureActorRagdollBlendControllers(ptr)[0].mState.mSetupState, 0u);
            const std::array<NifBullet::RagdollNativeKnockdownControllerSetupRequest, 2> badCompound{{
                {8, {1, 0, 0}, .25f}, {999, {}, .25f}}};
