            ASSERT_TRUE(temporary.isEnabled());
            orphan = temporary.prepareSound3D({}, definition.mId, 1.f, 1.f,
                MWSound::Type::Sfx, MWSound::PlayMode::Loop);
            ASSERT_TRUE(orphan);
