        MWWorld::LiveCellRef<ESM4::Armor> drop(placed, world.getStore().search<ESM4::Armor>(shieldKey));
        drop.mRef.setNativeItemCondition(0);
        drop.mRef.setEnchantmentCharge(7.25f);
        NifBullet::ActorRagdollDefinition definition;
