        auto values = *service.findActorValues(actor.getCellRef().getFormKey());
        values.mBounty = ESM4::CrimeBountyState{10.5f, 0.f};
        values.mValues[37].mModifiers = {.5f, -3.25f, -.25f};
        service.publishNonPlayerValues(actor, values);
