TEST(OblivionWorldTest, PreparedReferencePayloadOwnsStringsAnimationsAndPreservesRestoreFlags)
{
    PopulatedMigrationFixture fixture;
    ESM::ObjectState state; state.blank();
    state.mRef.mRefID = ESM::RefId::stringRefId("owned-reference-state");
    state.mRef.mGlobalVariable = std::string(192, 'g');
    state.mRef.mDestCell = std::string(192, 'd');
    state.mRef.mCount = 17;
    state.mFlags = 7; // SuppressActivate is cleared; OnActivate and ActivationBuffered survive.
    state.mPosition.pos[0] = 42.f;
    state.mAnimationState.mScriptedAnims.resize(2);
    state.mAnimationState.mScriptedAnims[0].mGroup = std::string(192, 'a');
    state.mAnimationState.mScriptedAnims[1].mGroup = "idle";
    state.mAnimationState.mScriptedAnims[1].mAbsolute = true;
    state.mAnimationState.mScriptedAnims[1].mTime = 2.5f;
    state.mAnimationState.mScriptedAnims[1].mLoopCount = 0x100000003ull;
    MWWorld::LiveCellRefBase::PreparedState original(state);
    MWWorld::LiveCellRefBase::PreparedState prepared(std::move(original));
    // Release every owned source buffer. Only late identity/enabled corrections
    // are read during install; the rest must have been prepared independently.
    state.mRef.mGlobalVariable.clear(); state.mRef.mGlobalVariable.shrink_to_fit();
    state.mRef.mDestCell.clear(); state.mRef.mDestCell.shrink_to_fit();
    state.mAnimationState.mScriptedAnims.clear(); state.mAnimationState.mScriptedAnims.shrink_to_fit();
    state.mRef.mRefNum = {400, 3}; state.mEnabled = true;
    MWWorld::LiveCellRef<ESM::Weapon> target(ESM::makeBlankCellRef());
    target.mData.setDeletedByContentFile(true);
    EXPECT_THROW(original.install(target, state), std::logic_error);
    auto wrong = state; wrong.mRef.mRefID = ESM::RefId::stringRefId("wrong-base");
    EXPECT_THROW(prepared.install(target, wrong), std::logic_error);
    EXPECT_TRUE(target.mRef.getRefId().empty());
    prepared.install(target, state);
    EXPECT_EQ(target.mRef.getRefNum(), state.mRef.mRefNum);
    EXPECT_EQ(target.mRef.getGlobalVariable(), std::string(192, 'g'));
    EXPECT_EQ(target.mRef.getCount(), 17);
    EXPECT_TRUE(target.mData.isDeletedByContentFile()); EXPECT_TRUE(target.mData.isEnabled());
    EXPECT_TRUE(target.mData.hasChanged()); EXPECT_FALSE(target.mData.mPhysicsPostponed);
    EXPECT_FALSE(target.mData.hasCustomData()); EXPECT_EQ(target.mData.getLuaScripts(), nullptr);
    ESM::ObjectState output; output.blank(); target.mRef.writeState(output); target.mData.write(output);
    EXPECT_EQ(output.mRef.mDestCell, std::string(192, 'd'));
    EXPECT_EQ(output.mFlags, 6u); EXPECT_EQ(output.mPosition.pos[0], 42.f);
    ASSERT_EQ(output.mAnimationState.mScriptedAnims.size(), 2u);
    EXPECT_EQ(output.mAnimationState.mScriptedAnims[0].mGroup, std::string(192, 'a'));
    EXPECT_TRUE(output.mAnimationState.mScriptedAnims[1].mAbsolute);
    EXPECT_EQ(output.mAnimationState.mScriptedAnims[1].mTime, 2.5f);
    EXPECT_EQ(output.mAnimationState.mScriptedAnims[1].mLoopCount, 0x100000003ull);
    EXPECT_THROW(prepared.install(target, state), std::logic_error);
    EXPECT_EQ(target.mRef.getCount(), 17);
}

TEST(OblivionWorldTest, PreparedPlayerReferencePayloadBindsToOneReferenceAndCancels)
{
    PopulatedMigrationFixture fixture;
    auto& world = fixture.mWorld; auto& model = world.getWorldModel();
    ESM::ObjectState state; state.blank(); state.mRef.mRefID = ESM::RefId::stringRefId("Player");
    MWWorld::ManualRef alias(world.getStore(), state.mRef.mRefID);
    const auto prepare = [&] { return std::make_unique<MWWorld::LiveCellRefBase::PreparedState>(state); };
    model.setPreparedPlayerState(prepare(), world.getPlayerPtr());
    EXPECT_FALSE(model.takePreparedPlayerState(alias.getPtr()));
    EXPECT_TRUE(model.takePreparedPlayerState(world.getPlayerPtr()));
    EXPECT_FALSE(model.takePreparedPlayerState(world.getPlayerPtr()));
    model.setPreparedPlayerState(prepare(), world.getPlayerPtr()); model.finishCellReferenceRestore();
    EXPECT_FALSE(model.takePreparedPlayerState(world.getPlayerPtr()));
    model.setPreparedPlayerState(prepare(), world.getPlayerPtr()); model.clear();
    EXPECT_FALSE(model.takePreparedPlayerState(world.getPlayerPtr()));
    EXPECT_THROW(model.setPreparedPlayerState(prepare(), {}), std::logic_error);
}

namespace
{
    void loadDialogueContent(MWWorld::ESMStore& store, std::string name)
    {
        ESM::Dialogue data{}; data.blank(); data.mStringId = name;
        data.mId = ESM::RefId::stringRefId(name); data.mType = ESM::Dialogue::Topic;
        auto stream = std::make_unique<std::stringstream>(); ESM::ESMWriter writer; writer.setFormatVersion(ESM::CurrentSaveGameFormatVersion); writer.save(*stream);
        writer.startRecord(ESM::REC_DIAL); data.save(writer, false); writer.endRecord(ESM::REC_DIAL); writer.close();
        ESM::ESMReader reader; reader.open(std::move(stream), "manager-dialogue-content");
        reader.getRecName(); reader.getRecHeader(); store.getWritable<ESM::Dialogue>().load(reader);
        store.getWritable<ESM::Dialogue>().setUp();
    }

    void readDialogueState(MWDialogue::DialogueManager& manager, const ESM::DialogueState& state)
    {
        auto stream = std::make_unique<std::stringstream>(); ESM::ESMWriter writer; writer.setFormatVersion(ESM::CurrentSaveGameFormatVersion); writer.save(*stream);
        writer.startRecord(ESM::REC_DIAS); state.save(writer); writer.endRecord(ESM::REC_DIAS); writer.close();
        ESM::ESMReader reader; reader.open(std::move(stream), "manager-dialogue-state");
        reader.getRecName(); reader.getRecHeader(); manager.readRecord(reader, ESM::REC_DIAS);
    }

    ESM::DialogueState dialogueState(MWDialogue::DialogueManager& manager)
    {
        auto stream = std::make_unique<std::stringstream>(); ESM::ESMWriter writer; writer.setFormatVersion(ESM::CurrentSaveGameFormatVersion); writer.save(*stream);
        Loading::Listener listener; manager.write(writer, listener); writer.close();
        ESM::ESMReader reader; reader.open(std::move(stream), "manager-dialogue-output");
        reader.getRecName(); reader.getRecHeader(); ESM::DialogueState state; state.load(reader); return state;
    }

    void readDeathCounts(MWMechanics::MechanicsManager& manager, const std::map<ESM::RefId, int>& counts)
    {
        auto stream = std::make_unique<std::stringstream>(); ESM::ESMWriter writer; writer.setFormatVersion(ESM::CurrentSaveGameFormatVersion); writer.save(*stream);
        writer.startRecord(ESM::REC_DCOU);
        for (const auto& [id, count] : counts) { writer.writeHNCRefId("ID__", id); writer.writeHNT("COUN", count); }
        writer.endRecord(ESM::REC_DCOU); writer.close();
        ESM::ESMReader reader; reader.open(std::move(stream), "manager-deaths");
        reader.getRecName(); reader.getRecHeader(); manager.readRecord(reader, ESM::REC_DCOU);
    }

    ESM::StolenItems stolenState(MWMechanics::MechanicsManager& manager)
    {
        auto stream = std::make_unique<std::stringstream>(); ESM::ESMWriter writer; writer.setFormatVersion(ESM::CurrentSaveGameFormatVersion); writer.save(*stream);
        Loading::Listener listener; manager.write(writer, listener); writer.close();
        ESM::ESMReader reader; reader.open(std::move(stream), "manager-stolen-output"); ESM::StolenItems state;
        while (reader.hasMoreRecs())
        {
            auto type = reader.getRecName(); reader.getRecHeader();
            if (type == ESM::REC_STLN) state.load(reader); else reader.skipRecord();
        }
        return state;
    }
}

TEST(OblivionWorldTest, PreparedDialoguePreservesMergeReplacementAndLifecycleSemantics)
{
    NativeWorldFixture fixture;
    loadDialogueContent(fixture.mWorld.getStore(), "prepared-topic");
    Compiler::Extensions extensions; Translation::Storage translation;
    auto manager = std::make_unique<MWDialogue::DialogueManager>(extensions, translation);
    ESM::DialogueState old; old.mChangedFactionReaction[ESM::RefId::stringRefId("a")][ESM::RefId::stringRefId("b")] = 11;
    readDialogueState(*manager, old);
    ESM::DialogueState state; state.mKnownTopics = {ESM::RefId::stringRefId("prepared-topic"),
        ESM::RefId::stringRefId("missing-topic"), ESM::RefId::stringRefId("prepared-topic")};
    state.mChangedFactionReaction[ESM::RefId::stringRefId("a")][ESM::RefId::stringRefId("b")] = 13;
    state.mChangedFactionReaction[ESM::RefId::stringRefId("removed-faction")][ESM::RefId::stringRefId("other")] = -17;
    const auto expected = state.mChangedFactionReaction; MWWorld::ESMStore incoming;
    auto apply = manager->prepareDialogueState(std::move(state), incoming); auto copy = apply;
    EXPECT_FALSE(apply()); EXPECT_EQ(dialogueState(*manager).mChangedFactionReaction, old.mChangedFactionReaction);
    manager->clear(); manager->addTopic(ESM::RefId::stringRefId("added-during-restore"));
    ASSERT_TRUE(apply()); EXPECT_FALSE(copy());
    auto actual = dialogueState(*manager); EXPECT_EQ(actual.mChangedFactionReaction, expected);
    EXPECT_EQ(actual.mKnownTopics, (std::vector<ESM::RefId>{ESM::RefId::stringRefId("added-during-restore"),
        ESM::RefId::stringRefId("prepared-topic")}));
    ESM::DialogueState empty; apply = manager->prepareDialogueState(std::move(empty), incoming);
    manager->clear(); manager->clear(); EXPECT_FALSE(apply());
    apply = manager->prepareDialogueState(ESM::DialogueState{}, incoming); manager.reset(); EXPECT_FALSE(apply());
}

TEST(OblivionWorldTest, PreparedMechanicsMapsOwnIncomingDefinitionsAndPreserveRecordSemantics)
{
    NativeWorldFixture fixture; auto& store = fixture.mWorld.getStore();
    MWWorld::ESMStore incoming;
    const auto native = ESM::RefId(ESM::FormId{0x800, 0});
    const auto missing = ESM::RefId::stringRefId("missing-death-base");
    ESM::Weapon saved{}; saved.blank(); saved.mId = incoming.generateId();
    incoming.getWritable<ESM::Weapon>().insert(saved); incoming.rebuildIdsIndex();
    // Content records must precede the dynamic suffix in the store's shared list.
    const auto kept = ESM::RefId::stringRefId("kept-death-base");
    auto immutable = saved; immutable.mId = kept; store.getWritable<ESM::Weapon>().insertStatic(immutable);
    auto transient = saved; transient.mId = ESM::RefId::stringRefId("outgoing-only-death-base");
    store.getWritable<ESM::Weapon>().insert(transient); store.rebuildIdsIndex();
    auto manager = std::make_unique<MWMechanics::MechanicsManager>();
    readDeathCounts(*manager, {{native, 9}});
    auto deaths = manager->prepareDeathCounts({{native, 3}, {saved.mId, 7}, {missing, 5}, {transient.mId, 6}}, incoming);
    ESM::StolenItems items; const auto item = ESM::RefId::stringRefId("owned-stolen-item");
    items.mStolenItems[item][{ESM::RefId::stringRefId("owner"), false}] = 4;
    items.mStolenItems[item][{ESM::RefId::stringRefId("faction"), true}] = 8;
    const auto expected = items.mStolenItems; auto stolen = manager->prepareStolenItems(std::move(items));
    auto copy = stolen; EXPECT_FALSE(deaths()); EXPECT_FALSE(stolen()); EXPECT_EQ(manager->countDeaths(native), 9);
    store.clearDynamic(); store.getWritable<ESM::Weapon>().insert(saved); store.rebuildIdsIndex();
    ASSERT_TRUE(store.find(kept));
    manager->clear(); readDeathCounts(*manager, {{native, 99}, {saved.mId, 42}, {kept, 12}});
    ASSERT_EQ(manager->countDeaths(kept), 12);
    ESM::StolenItems intervening;
    intervening.mStolenItems[ESM::RefId::stringRefId("intervening-item")][{kept, false}] = 99;
    auto stream = std::make_unique<std::stringstream>(); ESM::ESMWriter writer; writer.setFormatVersion(ESM::CurrentSaveGameFormatVersion); writer.save(*stream);
    writer.startRecord(ESM::REC_STLN); intervening.write(writer); writer.endRecord(ESM::REC_STLN); writer.close();
    ESM::ESMReader reader; reader.open(std::move(stream), "intervening-stolen"); reader.getRecName(); reader.getRecHeader();
    manager->readRecord(reader, ESM::REC_STLN);
    ASSERT_TRUE(deaths()); ASSERT_TRUE(stolen()); EXPECT_FALSE(copy()); EXPECT_FALSE(deaths());
    EXPECT_EQ(manager->countDeaths(native), 3); EXPECT_EQ(manager->countDeaths(saved.mId), 7);
    EXPECT_EQ(manager->countDeaths(kept), 12);
    EXPECT_EQ(manager->countDeaths(missing), 0); EXPECT_EQ(manager->countDeaths(transient.mId), 0);
    EXPECT_EQ(stolenState(*manager).mStolenItems, expected);
    auto empty = manager->prepareStolenItems(ESM::StolenItems{}); manager->clear(); ASSERT_TRUE(empty());
    EXPECT_TRUE(stolenState(*manager).mStolenItems.empty());
    auto stale = manager->prepareDeathCounts({}, incoming); manager->clear(); manager->clear(); EXPECT_FALSE(stale());
    auto dead = manager->prepareStolenItems(ESM::StolenItems{}); manager.reset(); EXPECT_FALSE(dead());
}


TEST(OblivionWorldTest, NativeScriptRetentionRestoresActualInstancesWithoutDispatch)
{
    PopulatedMigrationFixture fixture(true);
    auto& world = fixture.mWorld;
    auto& scripts = *world.getOblivionScriptManager();
    ASSERT_TRUE(scripts.dispatchObjectEvent(fixture.mActor, "onactivate", world.getPlayerPtr()));
    ESM4::RuntimeState before;
    scripts.capture(before);
    ASSERT_EQ(before.mScriptInstances.size(), 1u);
    auto incoming = before;
    incoming.mScriptInstances.front().mLocals.front() = std::int64_t{41};
    incoming.mScriptEventSequence += 20;
    auto install = scripts.prepareRestore(incoming);
    auto retained = scripts.retainRuntime();
    EXPECT_THROW(scripts.clear(), std::logic_error);
    EXPECT_THROW(scripts.update(0), std::logic_error);
    EXPECT_THROW(scripts.dispatchObjectEvent(fixture.mActor, "onactivate", world.getPlayerPtr()), std::logic_error);
    EXPECT_THROW(scripts.call("ModPCFame", {}, {std::int64_t{1}}, {}, {}), std::logic_error);
    EXPECT_FALSE(install.commit());
    ASSERT_TRUE(retained.detach());
    EXPECT_FALSE(retained.detach());
    ASSERT_TRUE(install.commit());
    ESM4::RuntimeState candidate;
    scripts.capture(candidate);
    EXPECT_EQ(candidate.mScriptInstances, incoming.mScriptInstances);
    ASSERT_TRUE(scripts.dispatchObjectEvent(fixture.mActor, "onactivate", world.getPlayerPtr()));
    ASSERT_TRUE(retained.exchange());
    ESM4::RuntimeState selected;
    scripts.capture(selected);
    EXPECT_EQ(selected.mScriptInstances, before.mScriptInstances);
    ASSERT_TRUE(retained.exchange());
    scripts.capture(selected);
    EXPECT_EQ(std::get<std::int64_t>(selected.mScriptInstances.front().mLocals.front()), 42);
    ASSERT_TRUE(retained.restore());
    EXPECT_FALSE(retained.restore());
    ESM4::RuntimeState restored;
    scripts.capture(restored);
    EXPECT_EQ(restored.mScriptInstances, before.mScriptInstances);
    EXPECT_EQ(restored.mScriptEventSequence, before.mScriptEventSequence);
    ASSERT_TRUE(scripts.dispatchObjectEvent(fixture.mActor, "onactivate", world.getPlayerPtr()));
    scripts.capture(restored);
    EXPECT_EQ(std::get<std::int64_t>(restored.mScriptInstances.front().mLocals.front()), 2);
    MWWorld::OblivionScriptManager other(world, world.getStore(), world.getContentFiles());
    auto first = scripts.retainRuntime();
    auto second = other.retainRuntime();
    ASSERT_TRUE(first.detach());
    ASSERT_TRUE(second.detach());
    first = std::move(second); // restore the previous owner before adopting another handle
    scripts.capture(restored);
    EXPECT_EQ(std::get<std::int64_t>(restored.mScriptInstances.front().mLocals.front()), 2);
    EXPECT_FALSE(second.restore());
    EXPECT_TRUE(first.restore());
}

TEST(OblivionWorldTest, NativeScriptRetentionRestoresQuestNodesAndCommitsReplacement)
{
    PopulatedMigrationFixture fixture;
    auto& world = fixture.mWorld;
    auto& scripts = *world.getOblivionScriptManager();
    ESM4::Quest quest{};
    quest.mId = {0xa20, 0};
    quest.mFormKey = ESM::FormKey::content("headless.esm", 0xa20);
    quest.mData.flags = ESM4::Quest::Flag_StartGameEnabled;
    world.getStore().getWritable<ESM4::Quest>().insertStatic(quest, quest.mFormKey);
    auto snapshot = world.captureOblivionRuntimeState();
    ESM4::RuntimeQuestState completed;
    completed.mQuest = quest.mFormKey;
    completed.mStage = 100;
    completed.mCompletedStages = {50, 100};
    snapshot.mQuests = {completed};
    scripts.restore(snapshot);
    const auto* original = scripts.findQuestState(quest.mFormKey);
    ASSERT_NE(original, nullptr);
    {
        auto cancelled = scripts.retainRuntime();
        EXPECT_EQ(scripts.findQuestState(quest.mFormKey), original);
        EXPECT_EQ(*original, completed);
    }
    EXPECT_EQ(scripts.findQuestState(quest.mFormKey), original);
    {
        auto retained = scripts.retainRuntime();
        EXPECT_THROW(scripts.retainRuntime(), std::logic_error);
        auto moved = std::move(retained);
        EXPECT_FALSE(retained.detach());
        ASSERT_TRUE(moved.detach());
        const auto* fresh = scripts.findQuestState(quest.mFormKey);
        ASSERT_NE(fresh, nullptr);
        EXPECT_NE(fresh, original);
        EXPECT_EQ(fresh->mStage, 0);
        EXPECT_TRUE(fresh->mCompletedStages.empty());
        EXPECT_TRUE(fresh->mRunning);
        ASSERT_TRUE(moved.exchange());
        EXPECT_EQ(scripts.findQuestState(quest.mFormKey), original);
    }
    EXPECT_EQ(scripts.findQuestState(quest.mFormKey), original);
    EXPECT_EQ(*original, completed);
    auto retained = scripts.retainRuntime();
    ASSERT_TRUE(retained.detach());
    scripts.restore(snapshot);
    const auto* replacement = scripts.findQuestState(quest.mFormKey);
    EXPECT_NE(replacement, original);
    ASSERT_TRUE(retained.exchange());
    EXPECT_EQ(scripts.findQuestState(quest.mFormKey), original);
    retained.discard();
    EXPECT_FALSE(retained.restore());
    EXPECT_EQ(scripts.findQuestState(quest.mFormKey), replacement);
    EXPECT_EQ(*replacement, completed);
    EXPECT_NO_THROW(scripts.clear());
}

