TEST(OblivionWorldTest, NativeWeaponFactoryPassiveBindingPreservesEmbeddedControllerTraversal)
{
    NativeWeaponFactoryFixture fixture;
    const auto carried = fixture.mAnimation->captureCarriedWeaponBody(fixture.mItem);
    ASSERT_TRUE(carried); ASSERT_TRUE(carried->mDefinition);
    osg::ref_ptr<osg::Group> parent = new osg::Group;
    MWRender::ObjectAnimation animation(fixture.mResident, parent, "meshes/factory-weapon.nif",
        &fixture.mResources, false, true);
    NativeWeaponTargetVisitor find;
    animation.getObjectRoot()->accept(find); ASSERT_TRUE(find.mTarget);
    struct Controller : SceneUtil::KeyframeController, osg::NodeCallback
    {
        unsigned mVisits = 0;
        osg::Callback* getAsCallback() override { return this; }
        void operator()(osg::Node* node, osg::NodeVisitor* visitor) override
        {
            ++mVisits;
            traverse(node, visitor);
        }
    };
    osg::ref_ptr<Controller> controller = new Controller;
    find.mTarget->addUpdateCallback(controller);
    const auto* callback = find.mTarget->getUpdateCallback();
    animation.bindLoosePhysicalPose(*carried->mDefinition, Nif::NiTransform::getIdentity());
    EXPECT_EQ(find.mTarget->getUpdateCallback(), callback);
    EXPECT_FALSE(animation.hasPhysicalPose());
    animation.runAnimation(.1f);
    osgUtil::UpdateVisitor visitor;
    osg::ref_ptr<osg::FrameStamp> stamp = new osg::FrameStamp;
    stamp->setFrameNumber(1); stamp->setSimulationTime(.1); stamp->setReferenceTime(.1);
    visitor.setFrameStamp(stamp); visitor.setTraversalNumber(1);
    animation.getObjectRoot()->accept(visitor);
    EXPECT_EQ(controller->mVisits, 1u);
    EXPECT_TRUE(animation.getLoosePhysicalPose()->isValid());
}

TEST(OblivionWorldTest, NativeWeaponFactorySceneLinkLeasesTheExactPublishedAnimation)
{
    NativeWeaponFactoryFixture fixture;
    const auto carried = fixture.mAnimation->captureCarriedWeaponDrop(fixture.mItem, fixture.mWorld.getStore());
    ASSERT_TRUE(carried); ASSERT_TRUE(carried->mReferenceDefinition);
    auto plan = fixture.prepare(); ASSERT_TRUE(plan->isValid());
    const auto reference = plan->references().front();
    EXPECT_THROW(fixture.mPhysics->captureLooseObjectSceneBinding(reference), std::invalid_argument);
    ASSERT_FALSE(plan->commit().isEmpty());
    const auto binding = fixture.mPhysics->captureLooseObjectSceneBinding(reference);
    ASSERT_TRUE(binding);
    const auto sceneTarget = fixture.mPhysics->captureLooseObjectSceneTarget(reference);
    EXPECT_EQ(sceneTarget.mNodeRecord, carried->mReferenceDefinition->mBodies.front().mNodeRecord);
    EXPECT_TRUE(fixture.mPhysics->captureLooseObjectTargetPose(reference, sceneTarget));
    EXPECT_TRUE(binding->matches(*carried->mReferenceDefinition));
    EXPECT_TRUE(binding->isValidFor(reference, true));
    const auto lease = binding->lockAnimation(reference);
    ASSERT_TRUE(lease);
    EXPECT_EQ(lease.get(), fixture.mObjects->getAnimation(reference));
    EXPECT_EQ(lease->getPtr(), reference);
    EXPECT_EQ(lease->getObjectRoot()->getParent(0), reference.getRefData().getBaseNode());
    // Publication-plan destruction must not retire the live model's link.
    plan.reset();
    EXPECT_EQ(fixture.mPhysics->captureLooseObjectSceneBinding(reference), binding);
    EXPECT_EQ(binding->lockAnimation(reference), lease);
    auto wrong = *carried->mReferenceDefinition;
    wrong.mSourceHash += " changed"; EXPECT_FALSE(binding->matches(wrong));
    wrong = *carried->mReferenceDefinition; ++wrong.mBodies.front().mRecord; EXPECT_FALSE(binding->matches(wrong));
    wrong = *carried->mReferenceDefinition; ++wrong.mBodies.front().mNodeRecord; EXPECT_FALSE(binding->matches(wrong));
    wrong = *carried->mReferenceDefinition; wrong.mBodies.front().mCollisionFlags ^= 8; EXPECT_FALSE(binding->matches(wrong));
    wrong = *carried->mReferenceDefinition; wrong.mReferenceRoot.reset(); EXPECT_FALSE(binding->matches(wrong));
    NativeWeaponTargetVisitor target;
    lease->getObjectRoot()->accept(target); ASSERT_TRUE(target.mTarget);
    const auto originalName = target.mTarget->getName();
    target.mTarget->setName("changed live physical node identity");
    EXPECT_FALSE(binding->isValidFor(reference, true));
    EXPECT_THROW(fixture.mPhysics->captureLooseObjectSceneBinding(reference), std::invalid_argument);
    target.mTarget->setName(originalName);
    EXPECT_TRUE(binding->isValidFor(reference, true));
}

TEST(OblivionWorldTest, NativeWeaponFactorySceneLinkRetiresDespiteHeldAnimationCheckpointAndHandle)
{
    for (unsigned removal = 0; removal < 4; ++removal)
    {
        SCOPED_TRACE(removal);
        NativeWeaponFactoryFixture fixture;
        auto plan = fixture.prepare(); ASSERT_TRUE(plan->isValid());
        const auto reference = plan->commit(); ASSERT_FALSE(reference.isEmpty());
        auto binding = fixture.mPhysics->captureLooseObjectSceneBinding(reference); ASSERT_TRUE(binding);
        const auto sceneTarget = fixture.mPhysics->captureLooseObjectSceneTarget(reference);
        const auto lease = binding->lockAnimation(reference); ASSERT_TRUE(lease);
        const auto checkpoint = lease->getLoosePhysicalPose()->captureLocalPose();
        osg::ref_ptr<SceneUtil::PositionAttitudeTransform> placement = reference.getRefData().getBaseNode();
        plan.reset();
        if (removal == 0)
        {
            ASSERT_TRUE(fixture.mObjects->removeObject(reference));
        }
        if (removal == 1)
        {
            auto prepared = fixture.mObjects->prepareModelRemoval(reference);
            ASSERT_TRUE(prepared->isValid()); ASSERT_TRUE(prepared->commit());
        }
        if (removal == 2) fixture.mObjects->removeCell(reference.getCell());
        if (removal == 3) fixture.mObjects.reset();
        EXPECT_TRUE(lease.valid());
        EXPECT_FALSE(binding->isValidFor(reference));
        EXPECT_FALSE(binding->lockAnimation(reference));
        EXPECT_THROW(fixture.mPhysics->captureLooseObjectSceneBinding(reference), std::invalid_argument);
        EXPECT_THROW(fixture.mPhysics->captureLooseObjectSceneTarget(reference), std::invalid_argument);
        EXPECT_THROW(fixture.mPhysics->captureLooseObjectTargetPose(reference, sceneTarget), std::invalid_argument);
        // Restoring the old placement and retaining the local checkpoint cannot
        // resurrect this model registration, even while all objects survive.
        reference.getRefData().setBaseNode(placement);
        EXPECT_FALSE(binding->isValidFor(reference));
        EXPECT_FALSE(binding->lockAnimation(reference));
        const auto before = reference.getRefData().getPosition();
        const auto physical = fixture.mPhysics->captureLooseObject(reference);
        EXPECT_THROW(MWWorld::synchronizeLooseWeaponPoses(fixture.mWorld, *fixture.mPhysics), std::invalid_argument);
        EXPECT_EQ(reference.getRefData().getPosition(), before);
        const auto after = fixture.mPhysics->captureLooseObject(reference);
        ASSERT_EQ(after.size(), physical.size());
        ASSERT_EQ(after.size(), 1u);
        EXPECT_EQ(after.front().mPose, physical.front().mPose);
        EXPECT_EQ(after.front().mLinearVelocity, physical.front().mLinearVelocity);
        EXPECT_EQ(after.front().mAngularVelocity, physical.front().mAngularVelocity);
        binding.reset();
        EXPECT_THROW(fixture.mPhysics->captureLooseObjectSceneBinding(reference), std::invalid_argument);
        EXPECT_TRUE(fixture.mPhysics->hasLooseObject(reference));
        fixture.mPhysics->removeLooseObject(reference);
        reference.getRefData().setBaseNode(nullptr);
    }
}

TEST(OblivionWorldTest, NativeWeaponFactoryCancelledPreparedSceneLinkInvalidatesDetachedPhysicalAdmission)
{
    for (const bool rollback : {false, true})
    {
        SCOPED_TRACE(rollback);
        NativeWeaponFactoryFixture fixture;
        const auto carried = fixture.mAnimation->captureCarriedWeaponDrop(fixture.mItem, fixture.mWorld.getStore());
        ASSERT_TRUE(carried); ASSERT_TRUE(carried->mReferenceDefinition);
        auto plan = fixture.prepare(); ASSERT_TRUE(plan->isValid());
        const auto reference = plan->references().front();
        auto model = fixture.mObjects->prepareModel(reference, "meshes/factory-weapon.nif", osg::Quat(),
            MWRender::Mask_Object, carried->mReferenceDefinition.get());
        const auto binding = model->looseSceneBinding(); ASSERT_TRUE(binding);
        EXPECT_TRUE(binding->isValidFor(reference));
        EXPECT_FALSE(binding->isValidFor(reference, true));
        EXPECT_FALSE(binding->lockAnimation(reference));
        const std::array<btTransform, 1> poses{btTransform::getIdentity()};
        auto physical = fixture.mPhysics->prepareLooseObject(reference, *carried->mReferenceDefinition,
            NifBullet::RagdollNativeLengthScale, poses, 1, -1, binding);
        EXPECT_TRUE(fixture.mPhysics->validatePreparedLooseObject(*physical));
        EXPECT_FALSE(fixture.mPhysics->commitLooseObject(*physical));
        EXPECT_TRUE(fixture.mPhysics->validatePreparedLooseObject(*physical));
        EXPECT_FALSE(fixture.mPhysics->hasLooseObject(reference));
        auto wrong = *carried->mReferenceDefinition; wrong.mSourceHash += " wrong";
        EXPECT_THROW(fixture.mPhysics->prepareLooseObject(reference, wrong,
            NifBullet::RagdollNativeLengthScale, poses, 1, -1, binding), std::invalid_argument);
        osg::ref_ptr<MWRender::ObjectAnimation> lease;
        if (rollback)
        {
            ASSERT_TRUE(fixture.mObjects->commitModel(*model));
            lease = binding->lockAnimation(reference);
            ASSERT_TRUE(lease);
            EXPECT_TRUE(fixture.mPhysics->validatePreparedLooseObject(*physical));
            ASSERT_TRUE(fixture.mObjects->rollbackModelAdmission(*model));
        }
        model.reset();
        EXPECT_FALSE(binding->isValidFor(reference));
        EXPECT_FALSE(fixture.mPhysics->validatePreparedLooseObject(*physical));
        EXPECT_FALSE(fixture.mPhysics->commitLooseObject(*physical));
        EXPECT_FALSE(fixture.mPhysics->hasLooseObject(reference));
        EXPECT_EQ(reference.getRefData().getBaseNode(), nullptr);
        EXPECT_EQ(fixture.mRoot->getNumChildren(), 0u);
        EXPECT_TRUE(plan->isValid());
    }
}

TEST(OblivionWorldTest, NativeWeaponFactorySceneLinkNeverFollowsAReplacementModel)
{
    NativeWeaponFactoryFixture fixture;
    const auto carried = fixture.mAnimation->captureCarriedWeaponDrop(fixture.mItem, fixture.mWorld.getStore());
    ASSERT_TRUE(carried); ASSERT_TRUE(carried->mReferenceDefinition);
    auto plan = fixture.prepare(); ASSERT_TRUE(plan->isValid());
    const auto reference = plan->commit(); ASSERT_FALSE(reference.isEmpty());
    const auto oldBinding = fixture.mPhysics->captureLooseObjectSceneBinding(reference); ASSERT_TRUE(oldBinding);
    const auto oldAnimation = oldBinding->lockAnimation(reference); ASSERT_TRUE(oldAnimation);
    plan.reset();
    ASSERT_TRUE(fixture.mObjects->removeObject(reference));
    auto model = fixture.mObjects->prepareModel(reference, "meshes/factory-weapon.nif", osg::Quat(),
        MWRender::Mask_Object, carried->mReferenceDefinition.get());
    const auto replacement = model->looseSceneBinding(); ASSERT_TRUE(replacement);
    ASSERT_TRUE(fixture.mObjects->commitModel(*model));
    const auto newAnimation = replacement->lockAnimation(reference); ASSERT_TRUE(newAnimation);
    EXPECT_NE(newAnimation, oldAnimation);
    EXPECT_EQ(newAnimation.get(), fixture.mObjects->getAnimation(reference));
    EXPECT_FALSE(oldBinding->isValidFor(reference));
    EXPECT_FALSE(oldBinding->lockAnimation(reference));
    EXPECT_THROW(fixture.mPhysics->captureLooseObjectSceneBinding(reference), std::invalid_argument);
}

TEST(OblivionWorldTest, NativeWeaponFactoryLinkedPhysicsWaitsForScenePublicationWithoutConsumingPreparation)
{
    NativeWeaponFactoryFixture fixture;
    const auto carried = fixture.mAnimation->captureCarriedWeaponDrop(fixture.mItem, fixture.mWorld.getStore());
    ASSERT_TRUE(carried); ASSERT_TRUE(carried->mReferenceDefinition);
    auto plan = fixture.prepare(); ASSERT_TRUE(plan->isValid());
    const auto reference = plan->references().front();
    auto model = fixture.mObjects->prepareModel(reference, "meshes/factory-weapon.nif", osg::Quat(),
        MWRender::Mask_Object, carried->mReferenceDefinition.get());
    const auto binding = model->looseSceneBinding(); ASSERT_TRUE(binding);
    const std::array<btTransform, 1> poses{btTransform::getIdentity()};
    auto physical = fixture.mPhysics->prepareLooseObject(reference, *carried->mReferenceDefinition,
        NifBullet::RagdollNativeLengthScale, poses, 1, -1, binding);
    ASSERT_TRUE(fixture.mPhysics->validatePreparedLooseObject(*physical));
    EXPECT_FALSE(fixture.mPhysics->commitLooseObject(*physical));
    EXPECT_TRUE(fixture.mPhysics->validatePreparedLooseObject(*physical));
    EXPECT_FALSE(fixture.mPhysics->hasLooseObject(reference));
    EXPECT_EQ(fixture.mRoot->getNumChildren(), 0u);
    ASSERT_TRUE(fixture.mObjects->commitModel(*model));
    ASSERT_TRUE(fixture.mPhysics->commitLooseObject(*physical));
    EXPECT_FALSE(fixture.mPhysics->validatePreparedLooseObject(*physical));
    EXPECT_EQ(fixture.mPhysics->captureLooseObjectSceneBinding(reference), binding);
    const auto lease = binding->lockAnimation(reference); ASSERT_TRUE(lease);
    EXPECT_EQ(lease.get(), fixture.mObjects->getAnimation(reference));
    ASSERT_TRUE(fixture.mObjects->rollbackModelAdmission(*model));
    EXPECT_FALSE(binding->isValidFor(reference));
    EXPECT_THROW(fixture.mPhysics->captureLooseObjectSceneBinding(reference), std::invalid_argument);
    fixture.mPhysics->removeLooseObject(reference);
    EXPECT_TRUE(plan->isValid());
}

TEST(OblivionWorldTest, NativePowerPhasePersistsWithoutAnOrdinaryQueueAndConsumesOnlyOneAction)
{
    NativeWorldFixture fixture;
    auto& world = fixture.mWorld;
    const auto actor = addNativeNpc(fixture, 0x801);
    ASSERT_TRUE(world.activateOblivionActor(actor));
    auto& service = *world.getOblivionCombatService();
    const auto key = actor.getCellRef().getFormKey();
    service.initializeConstructedActorProcess(key);
    const auto id = service.beginMeleeStrike(key, ESM4::MeleeStrikeKind::StandingPower, "handtohandattackpower");
    ASSERT_TRUE(service.bindMeleePlayback(id, key));
    service.advanceAnimationClock(key, 0);
    ASSERT_TRUE(service.setMeleeSequenceTiming(id, key, {}));
    const std::array<float, 3> keys{0, .2f, 1};
    ASSERT_TRUE(service.advancePowerMeleeSequence(id, key, 0, 1, 0, 1, keys));
    EXPECT_FALSE(service.isMeleeContactPending(id, key));
    ASSERT_TRUE(service.advancePowerMeleeSequence(id, key, .2f, 1, 0, 1, keys));
    EXPECT_FALSE(service.isMeleeContactPending(id, key));
    ASSERT_TRUE(service.advancePowerMeleeSequence(id, key, .01f, 1, 0, 1, keys));
    ASSERT_TRUE(service.isMeleeContactPending(id, key));
    EXPECT_FALSE(service.isOrdinaryMeleeContactPending(id, key));
    EXPECT_FALSE(service.isMeleeContactPending(id + 1, key));
    EXPECT_FALSE(service.advanceOrdinaryMeleeSequence(id, key, .1f, 1, 0, 1, {0, .2f, .6f, 1}));
    const auto pending = captureNativeActorState(fixture, actor).serializeBinary();
    service.restore(ESM4::RuntimeState::deserializeBinary(pending), world.getStore());
    EXPECT_EQ(captureNativeActorState(fixture, actor).serializeBinary(), pending);
    EXPECT_TRUE(service.isMeleeContactPending(id, key));
    auto legacy = ESM4::RuntimeState::deserializeBinary(pending);
    legacy.mVersion = 48;
    legacy.mNativeMeleeStates.at(key).mStrike->mPowerPhase.reset();
    legacy.mNativeMeleeStates.at(key).mStrike->mOrdinaryPhase = ESM4::OrdinaryMeleePhase::Queue;
    service.restore(ESM4::RuntimeState::deserializeBinary(legacy.serializeBinary()), world.getStore());
    EXPECT_FALSE(service.isMeleeContactPending(id, key));
    ASSERT_TRUE(service.advancePowerMeleeSequence(id, key, 0, 1, 0, 1, keys));
    auto expectedMigration = ESM4::RuntimeState::deserializeBinary(pending);
    auto& timing = *expectedMigration.mNativeMeleeStates.at(key).mStrike->mSequenceTiming;
    // Active native manager updates copy the previous output to ease-start,
    // including on zero-duration frames (6CA950/6C5FC0).
    timing.mEaseStart = timing.mOutputTime;
    const auto migrated = expectedMigration.serializeBinary();
    EXPECT_EQ(captureNativeActorState(fixture, actor).serializeBinary(), migrated);
    // Missing physical context is neither a contact nor an acquired miss.
    EXPECT_FALSE(MWMechanics::commitOblivionMeleeContact(world, id, actor, {}, 64, 0, 0, false));
    EXPECT_EQ(captureNativeActorState(fixture, actor).serializeBinary(), migrated);
    const auto fatigue = service.getNonPlayerValue(actor, 10);
    // Exercise the existing transaction/restore anti-replay boundary separately
    // from acquisition; this is not a geometry or normal-input acceptance test.
    ASSERT_TRUE(world.commitOblivionPhysicalContact(id, actor, {}, {-35, 0, 0}));
    EXPECT_EQ(service.getNonPlayerValue(actor, 10), fatigue - 35);
    const auto consumed = captureNativeActorState(fixture, actor).serializeBinary();
    service.restore(ESM4::RuntimeState::deserializeBinary(consumed), world.getStore());
    EXPECT_FALSE(service.isMeleeContactPending(id, key));
    EXPECT_FALSE(world.commitOblivionPhysicalContact(id, actor, {}, {-35, 0, 0}));
    ASSERT_TRUE(service.advancePowerMeleeSequence(id, key, 1, 1, 0, 1, keys));
    EXPECT_EQ(service.findMeleeState(key)->mStrike->mPowerPhase, ESM4::PowerMeleePhase::End);
    EXPECT_EQ(service.findMeleeState(key)->mStrike->mOrdinaryPhase, ESM4::OrdinaryMeleePhase::Start);
    ASSERT_TRUE(service.finishMeleeStrike(id, key));
    EXPECT_EQ(service.getProcessAction(key), -1);
}

TEST(OblivionWorldTest, StandingPowerRecipesUseRawSkillAndMultiplyWeaponBeforeAttackBonus)
{
    NativeWorldFixture fixture;
    auto& world = fixture.mWorld;
    auto& store = world.getStore();
    const auto attacker = addNativeNpc(fixture, 0x801), victim = addNativeNpc(fixture, 0x802);
    ASSERT_TRUE(world.activateOblivionActor(attacker)); ASSERT_TRUE(world.activateOblivionActor(victim));
    unsigned id = 0x950;
    for (auto [name, value] : {std::pair{"fFatigueBase", 1.f}, {"fFatigueMult", 0.f},
        {"fDamageWeaponMult", 1.f}, {"fDamageSkillBase", 1.f}, {"fDamageSkillMult", 0.f},
        {"fDamageWeaponConditionBase", 1.f}, {"fDamageWeaponConditionMult", 0.f},
        {"fDamageStrengthBase", 1.f}, {"fDamageStrengthMult", 0.f},
        {"fHandHealthMin", 20.f}, {"fHandHealthMax", 20.f},
        {"fHandFatigueDamageBase", 10.f}, {"fHandFatigueDamageMult", 0.f},
        {"fDamagePowerAttackBonus", 2.5f}, {"fDamagePowerAttackStandBonus", 3.f},
        {"fDamageToWeaponPercentage", 0.f}})
    {
        ESM4::GameSetting setting{}; setting.mId = {id, 0}; setting.mEditorId = name; setting.mData = value;
        store.getWritable<ESM4::GameSetting>().insertStatic(setting, ESM::FormKey::content("headless.esm", id++));
    }
    const auto set = [&](std::uint8_t av, int value) {
        return world.executeOblivionActorValueCommand(attacker, av, ESM4::ActorValueCommand::Set,
            ESM4::ActorValueCommandSource::Script, value);
    };
    ASSERT_TRUE(set(42, 7)); ASSERT_TRUE(set(7, 100));
    const auto weaponKey = addEquipmentWeapon(fixture);
    auto weapon = *store.search<ESM4::Weapon>(weaponKey); weapon.mData.damage = 8;
    ESM4::RuntimeInventoryItem saved; saved.mBase = weaponKey; saved.mCount = 1;
    saved.mCondition = 100; saved.mEquippedSlots = ESM4::InventorySlotWeapon;
    installEquipmentInventory(fixture, attacker, {saved});
    auto& inventory = attacker.getClass().getInventoryStore(attacker);
    const auto item = *inventory.getSlot(MWWorld::InventoryStore::Slot_CarriedRight);
    const auto snapshot = [&] {
        auto state = captureNativeActorState(fixture, attacker);
        state.mReferences.push_back(captureNativeActorState(fixture, victim).mReferences.front());
        return state.serializeBinary();
    };
    for (unsigned type = 0; type < 4; ++type)
        for (int skill : {24, 25})
        {
            SCOPED_TRACE(::testing::Message() << type << ',' << skill);
            weapon.mData.type = type; store.getWritable<ESM4::Weapon>().insertStatic(weapon, weaponKey);
            ASSERT_TRUE(set(type < 2 ? 16 : 14, 100));
            ASSERT_TRUE(set(type < 2 ? 14 : 16, skill)); ASSERT_TRUE(set(17, skill));
            const auto before = snapshot();
            const auto hand = MWMechanics::resolveOblivionUnarmedMeleeContact(world, attacker, victim, 0, false,
                ESM4::MeleeStrikeKind::StandingPower);
            ASSERT_TRUE(hand); EXPECT_EQ(hand->mHealth, skill == 24 ? 50 : 60);
            EXPECT_EQ(hand->mFatigue, skill == 24 ? 25 : 30);
            const auto armed = MWMechanics::resolveOblivionWeaponMeleeContact(world, attacker, victim,
                item, 0, false, ESM4::MeleeStrikeKind::StandingPower);
            ASSERT_TRUE(armed); EXPECT_EQ(armed->mHealth, skill == 24 ? 27 : 31);
            EXPECT_EQ(MWMechanics::oblivionOrdinaryWeaponContactDamage(world, attacker, item), 15);
            EXPECT_FALSE(MWMechanics::resolveOblivionWeaponMeleeContact(world, attacker, victim,
                item, 0, false, ESM4::MeleeStrikeKind::LeftPower));
            EXPECT_EQ(snapshot(), before);
        }
}

TEST(OblivionWorldTest, NativePhysicalSourceBindsOwnedNifToTheActualRendererAndSequenceRoot)
{
    class SourceAnimation : public MWRender::Animation
    {
    public:
        SourceAnimation(const MWWorld::Ptr& actor, osg::Group* parent, Resource::ResourceSystem* resources,
            const std::string& model)
            : Animation(actor, parent, resources)
        { setObjectRoot(model, true, false, false); }
        void reload(const std::string& model) { setObjectRoot(model, true, false, false); }
        void bindReactionRoot(std::string name)
        {
            SceneUtil::ControllerSequenceMetadata sequence;
            sequence.mAccumRootName = std::move(name);
            bindNativeReactionRoot(std::span(&sequence, 1));
        }
    };
    NativeWorldFixture fixture;
    const auto actor = addNativeNpc(fixture, 0x900);
    const std::string model = "meshes/m15-physical-source.nif";
    const auto path = VFS::Path::toNormalized(model);
    std::filesystem::create_directories(fixture.mDirectory / "meshes");
    const auto write = [&](float radius) {
        std::ofstream file(fixture.mDirectory / model, std::ios::binary);
        const auto bytes = nativeCarriedWeaponNif(radius);
        file.write(bytes.data(), bytes.size());
        if (!file) throw std::runtime_error("failed to write owned physical-source NIF");
    };
    write(.5f);
    fixture.mVfs.addArchive(std::make_unique<VFS::FileSystemArchive>(fixture.mDirectory));
    fixture.mVfs.buildIndex();
    auto* scene = fixture.mResources.getSceneManager();
    scene->setShaderPath(std::filesystem::path(OPENMW_PROJECT_SOURCE_DIR) / "files/shaders");
    osg::ref_ptr<osg::Group> parent = new osg::Group;
    std::optional<MWRender::Animation::NativePhysicalSource> retained;
    {
        SourceAnimation animation(actor, parent, &fixture.mResources, model);
        auto initial = animation.captureNativePhysicalSource(path);
        ASSERT_TRUE(initial);
        ASSERT_TRUE(initial->definition());
        ASSERT_EQ(initial->definition()->mBodies.size(), 1u);
        EXPECT_FLOAT_EQ(std::get<NifBullet::RagdollSphere>(initial->definition()->mBodies[0].mShape).mRadius, .5f);
        EXPECT_FALSE(initial->reactionRootRecord());
        EXPECT_TRUE(animation.isCurrentNativePhysicalSource(*initial));
        EXPECT_FALSE(animation.hasPhysicalPose());
        const auto pose = initial->binding()->captureWorldBones(Nif::NiTransform::getIdentity());
        ASSERT_EQ(pose.size(), 1u);
        EXPECT_EQ(pose[0].mPose.getTrans(), osg::Vec3f(1, 2, 3));
        animation.bindReactionRoot("Owned weapon");
        EXPECT_FALSE(animation.isCurrentNativePhysicalSource(*initial));
        auto selected = animation.captureNativePhysicalSource(path);
        ASSERT_TRUE(selected);
        EXPECT_EQ(selected->reactionRootRecord(), 0u);
        EXPECT_TRUE(animation.isCurrentNativePhysicalSource(*selected));
        const auto rebound = addNativeNpc(fixture, 0x901);
        animation.updatePtr(rebound);
        EXPECT_FALSE(animation.isCurrentNativePhysicalSource(*selected));
        animation.updatePtr(actor);
        EXPECT_TRUE(animation.isCurrentNativePhysicalSource(*selected));
        SourceAnimation other(actor, parent, &fixture.mResources, model);
        EXPECT_FALSE(other.isCurrentNativePhysicalSource(*selected));
        // Reopening a changed parser asset cannot bind its new geometry to the
        // old visible model. The retained old source remains valid for that model.
        write(2.f);
        fixture.mResources.getNifFileManager()->clearCache();
        EXPECT_TRUE(animation.isCurrentNativePhysicalSource(*selected));
        EXPECT_THROW(animation.captureNativePhysicalSource(path), std::invalid_argument);
        scene->clearCache();
        animation.reload(model);
        EXPECT_FALSE(animation.isCurrentNativePhysicalSource(*selected));
        auto replacement = animation.captureNativePhysicalSource(path);
        ASSERT_TRUE(replacement);
        EXPECT_FLOAT_EQ(std::get<NifBullet::RagdollSphere>(replacement->definition()->mBodies[0].mShape).mRadius, 2.f);
        EXPECT_NE(replacement->definition()->mSourceHash, selected->definition()->mSourceHash);
        EXPECT_FALSE(replacement->reactionRootRecord());
        EXPECT_FALSE(animation.hasPhysicalPose());
        retained = std::move(replacement);
    }
    fixture.mResources.getNifFileManager()->clearCache();
    ASSERT_TRUE(retained);
    EXPECT_FLOAT_EQ(std::get<NifBullet::RagdollSphere>(retained->definition()->mBodies[0].mShape).mRadius, 2.f);
    SourceAnimation other(actor, parent, &fixture.mResources, model);
    EXPECT_FALSE(other.isCurrentNativePhysicalSource(*retained));
}

TEST(OblivionWorldTest, NativeGetKnockedStateUsesTheCommandTranslationAcrossScriptsAndConditions)
{
    NativeWorldFixture fixture;
    auto& world = fixture.mWorld;
    MWClass::Npc::registerSelf();
    world.setupPlayer();
    ESM4::Npc nativePlayer{};
    nativePlayer.mId = {7, 1};
    nativePlayer.mFormKey = ESM::FormKey::content("Oblivion.esm", 7);
    nativePlayer.mIsTES4 = true;
    nativePlayer.mData.health = 100;
    world.getStore().getWritable<ESM4::Npc>().insertStatic(nativePlayer, nativePlayer.mFormKey);
    ASSERT_TRUE(world.initializeOblivionPlayerActor());
    const auto player = world.getPlayerPtr();
    const auto npc = addNativeNpc(fixture, 0x801);
    const auto creature = addEquipmentCreature(fixture);
    const auto low = addNativeNpc(fixture, 0x802);
    ESM4::RuntimeState coldBefore;
    world.getOblivionCombatService()->capture(coldBefore);
    for (const auto& cold : {npc, creature, low})
    {
        const auto key = cold.getCellRef().getFormKey();
        const auto* customData = cold.getRefData().getCustomData();
        ASSERT_FALSE(world.getOblivionCombatService()->findActorValues(key));
        EXPECT_EQ(world.getOblivionScriptIsLeftUp(key), 1.0);
        ObScript::RuntimeContext context;
        context.mSelf = key;
        const auto reference = ObScript::Value{ObScript::ReferenceValue{key, {}}};
        EXPECT_EQ(ObScript::asNumber(world.getOblivionScriptManager()->call(
            "IsLeftUp", reference, {}, context, {})), 1.0);
        EXPECT_FALSE(world.getOblivionCombatService()->findActorValues(key));
        EXPECT_EQ(cold.getRefData().getCustomData(), customData);
    }
    ESM4::ActorCharacter unloaded{};
    unloaded.mId = {0x803, 0};
    unloaded.mFormKey = ESM::FormKey::content("headless.esm", 0x803);
    unloaded.mBaseObj = npc.get<ESM4::Npc>()->mBase->mId;
    unloaded.mBaseKey = npc.get<ESM4::Npc>()->mBase->mFormKey;
    world.getStore().getWritable<ESM4::ActorCharacter>().insertStatic(unloaded, unloaded.mFormKey);
    ASSERT_TRUE(world.getWorldModel().getPtr(unloaded.mId).isEmpty());
    EXPECT_EQ(world.getOblivionScriptIsLeftUp(unloaded.mFormKey), 1.0);
    EXPECT_FALSE(world.getOblivionCombatService()->findActorValues(unloaded.mFormKey));
    ESM4::RuntimeState coldAfter;
    world.getOblivionCombatService()->capture(coldAfter);
    EXPECT_EQ(coldAfter, coldBefore);
    ASSERT_TRUE(world.activateOblivionActor(npc));
    ASSERT_TRUE(world.activateOblivionActor(creature));
    ASSERT_TRUE(world.initializeOblivionNonPlayerActor(low, ESM4::ActorValueProcess::Low));
    auto& combat = *world.getOblivionCombatService();
    auto* scripts = world.getOblivionScriptManager();
    auto* ai = world.getOblivionAiService();
    ASSERT_NE(scripts, nullptr);
    ASSERT_NE(ai, nullptr);
    // Original evaluator4F76B0's stored outputs for all signed process bytes.
    // Its raw3/4 mapping differs from hand-contact suppression for any nonzero byte.
    for (const auto& actor : {npc, creature, low, player})
    {
        const auto key = actor == player ? ESM::FormKey::dynamic("player", 1) : actor.getCellRef().getFormKey();
        for (int raw = -128; raw <= 127; ++raw)
        {
            SCOPED_TRACE(::testing::Message() << key.serialize() << "," << raw);
            combat.setProcessKnockedState(key, static_cast<std::int8_t>(raw));
            const auto before = *combat.findActorValues(key);
            const double expected = actor != low && (raw == 3 || raw == 4) ? 1.0 : 0.0;
            ASSERT_EQ(world.getOblivionScriptKnockedState(key), expected);
            ObScript::RuntimeContext context;
            context.mSelf = key;
            const auto reference = ObScript::Value{ObScript::ReferenceValue{key, {}}};
            EXPECT_EQ(ObScript::asNumber(scripts->call("GetKnockedState", reference, {}, context, {})), expected);
            ESM4::PackageCondition condition;
            condition.mFunction = 107;
            condition.mOperator = ESM4::ConditionOperator::Equal;
            condition.mComparisonValue = static_cast<float>(expected);
            if (actor == player) condition.mRunOnTarget = true;
            const auto speaker = actor == player ? npc : actor;
            const auto target = actor == player ? player : MWWorld::Ptr{};
            EXPECT_EQ(ai->evaluateDialogueConditions(speaker, target, std::span(&condition, 1)), ESM4::ConditionResult::True);
            condition.mComparisonValue = static_cast<float>(1.0 - expected);
            EXPECT_EQ(ai->evaluateDialogueConditions(speaker, target, std::span(&condition, 1)), ESM4::ConditionResult::False);
            // Native IsLeftUp has no process/knocked-state gate. This
            // headless World has no Spine, which returns1 for every actor.
            EXPECT_EQ(world.getOblivionScriptIsLeftUp(key), 1.0);
            EXPECT_EQ(ObScript::asNumber(scripts->call("IsLeftUp", reference, {}, context, {})), 1.0);
            condition.mFunction = 285;
            condition.mComparisonValue = 1;
            EXPECT_EQ(ai->evaluateDialogueConditions(speaker, target, std::span(&condition, 1)), ESM4::ConditionResult::True);
            condition.mComparisonValue = 0;
            EXPECT_EQ(ai->evaluateDialogueConditions(speaker, target, std::span(&condition, 1)), ESM4::ConditionResult::False);
            EXPECT_EQ(*combat.findActorValues(key), before);
        }
    }
    EXPECT_FALSE(world.getOblivionScriptKnockedState(ESM::FormKey::content("headless.esm", 0xabcdef)));
    EXPECT_FALSE(world.getOblivionScriptIsLeftUp(ESM::FormKey::content("headless.esm", 0xabcdef)));
}

TEST(OblivionWorldTest, NativeIsLeftUpReadsPhysicalSpineAndScopedHorseFallback)
{
    class SourceAnimation : public MWRender::Animation
    {
    public:
        SourceAnimation(const MWWorld::Ptr& actor, osg::Group* parent, Resource::ResourceSystem* resources,
            const std::string& model) : Animation(actor, parent, resources)
        { setObjectRoot(model, true, false, false); }
    };
    NativeWorldFixture fixture;
    auto& world = fixture.mWorld;
    const auto npc = addNativeNpc(fixture, 0x900);
    const auto creature = addEquipmentCreature(fixture);
    auto creatureBase = *creature.get<ESM4::Creature>()->mBase;
    creatureBase.mBaseScale = 1;
    world.getStore().getWritable<ESM4::Creature>().insertStatic(creatureBase, creatureBase.mFormKey);
    ASSERT_TRUE(world.activateOblivionActor(npc));
    ASSERT_TRUE(world.activateOblivionActor(creature));
    ESM4::RuntimeState before;
    world.getOblivionCombatService()->capture(before);
    const std::string model = "meshes/m15-is-left-up.nif";
    std::filesystem::create_directories(fixture.mDirectory / "meshes");
    {
        std::ofstream file(fixture.mDirectory / model, std::ios::binary);
        const auto bytes = nativeCarriedWeaponNif(.5f, false, 1, false, false, "Bip01 Spine");
        file.write(bytes.data(), bytes.size());
        ASSERT_TRUE(file);
    }
    fixture.mVfs.addArchive(std::make_unique<VFS::FileSystemArchive>(fixture.mDirectory));
    fixture.mVfs.buildIndex();
    fixture.mResources.getSceneManager()->setShaderPath(
        std::filesystem::path(OPENMW_PROJECT_SOURCE_DIR) / "files/shaders");
    osg::ref_ptr<osg::Group> parent = new osg::Group;
    SourceAnimation animation(npc, parent, &fixture.mResources, model);
    SourceAnimation creatureAnimation(creature, parent, &fixture.mResources, model);
    const auto placement = Nif::NiTransform::getIdentity();
    EXPECT_THROW(world.getOblivionActorIsLeftUp(creature, animation, placement), std::invalid_argument);
    EXPECT_EQ(world.getOblivionActorIsLeftUp(npc, animation, placement), 1);
    const auto source = animation.captureNativePhysicalSource(VFS::Path::toNormalized(model));
    ASSERT_TRUE(source);
    auto poses = animation.beginPhysicalPose(
        *source->definition(), placement, MWRender::PhysicalPoseAnimation::AnimatedTargets);
    ASSERT_EQ(poses.size(), 1u);
    auto flip = osg::Matrixf::identity();
    flip(1, 1) = flip(2, 2) = -1;
    flip.setTrans(poses[0].mPose.getTrans());
    poses[0].mPose = flip;
    animation.applyPhysicalPose(poses, placement);
    EXPECT_EQ(world.getOblivionActorIsLeftUp(npc, animation, placement), 0);
    animation.endPhysicalPose();
    EXPECT_EQ(world.getOblivionActorIsLeftUp(npc, animation, placement), 1);
    auto* spine = const_cast<NifOsg::MatrixTransform*>(
        dynamic_cast<const NifOsg::MatrixTransform*>(creatureAnimation.getNode("Bip01 Spine")));
    ASSERT_NE(spine, nullptr);
    spine->setMatrix(flip);
    EXPECT_EQ(world.getOblivionActorIsLeftUp(creature, creatureAnimation, placement), 0);
    auto base = *creature.get<ESM4::Creature>()->mBase;
    base.mData.creatureType = 4;
    world.getStore().getWritable<ESM4::Creature>().insertStatic(base, base.mFormKey);
    EXPECT_EQ(world.getOblivionActorIsLeftUp(creature, creatureAnimation, placement), 1); // Horse ignores Bip01.
    osg::ref_ptr<NifOsg::MatrixTransform> second
        = new NifOsg::MatrixTransform(Nif::NiTransform::getIdentity());
    second->setName("Bip02 Spine");
    second->setMatrix(flip);
    spine->addChild(second); // Two flips give the second Spine positive world R22.
    EXPECT_EQ(world.getOblivionActorIsLeftUp(creature, creatureAnimation, placement), 1);
    base.mData.creatureType = 0;
    world.getStore().getWritable<ESM4::Creature>().insertStatic(base, base.mFormKey);
    EXPECT_EQ(world.getOblivionActorIsLeftUp(creature, creatureAnimation, placement), 0); // Prefer Bip01.
    spine->setName("bip01 spine");
    EXPECT_EQ(world.getOblivionActorIsLeftUp(creature, creatureAnimation, placement), 1); // Exact-case fallback.
    second->setName("Other");
    EXPECT_EQ(world.getOblivionActorIsLeftUp(creature, creatureAnimation, placement), 1); // Missing both.
    ESM4::RuntimeState after;
    world.getOblivionCombatService()->capture(after);
    EXPECT_EQ(after, before);
}

TEST(OblivionWorldTest, NativeCreatureRenderedScaleUsesAbsoluteStoredBnamProduct)
{
    NativeWorldFixture fixture;
    const auto actor = addEquipmentCreature(fixture);
    ESM4::RuntimeState before;
    fixture.mWorld.getOblivionCombatService()->capture(before);
    auto base = *actor.get<ESM4::Creature>()->mBase;
    for (const float baseScale : {-.25f, .25f, 0.f, -0.f})
    {
        base.mBaseScale = baseScale;
        fixture.mWorld.getStore().getWritable<ESM4::Creature>().insertStatic(base, base.mFormKey);
        for (const float referenceScale : {-2.f, 2.f, -0.f, 0.f})
        {
            osg::Vec3f scale(referenceScale, referenceScale, referenceScale);
            actor.getClass().adjustScale(actor, scale, false);
            for (unsigned axis = 0; axis < 3; ++axis)
                EXPECT_EQ(std::bit_cast<std::uint32_t>(scale[axis]), std::bit_cast<std::uint32_t>(referenceScale));
            actor.getClass().adjustScale(actor, scale, true);
            const float expected = baseScale == 0 || referenceScale == 0 ? 0.f : .5f;
            for (unsigned axis = 0; axis < 3; ++axis)
                EXPECT_EQ(std::bit_cast<std::uint32_t>(scale[axis]), std::bit_cast<std::uint32_t>(expected));
        }
    }
    base.mBaseScale = 1;
    fixture.mWorld.getStore().getWritable<ESM4::Creature>().insertStatic(base, base.mFormKey);
    osg::Vec3f invalid(2, std::numeric_limits<float>::infinity(), 2);
    EXPECT_THROW(actor.getClass().adjustScale(actor, invalid, true), std::invalid_argument);
    EXPECT_EQ(invalid.x(), 2);
    EXPECT_TRUE(std::isinf(invalid.y()));
    EXPECT_EQ(invalid.z(), 2);
    ESM4::RuntimeState after;
    fixture.mWorld.getOblivionCombatService()->capture(after);
    EXPECT_EQ(after, before);
}

TEST(OblivionWorldTest, NativePhysicalAdmissionJoinsRenderedGeometryCapsuleAndSavedAuthority)
{
    class SourceAnimation : public MWRender::Animation
    {
    public:
        bool mRejectControllerRebuild = false;
        SourceAnimation(const MWWorld::Ptr& actor, osg::Group* parent, Resource::ResourceSystem* resources,
            const std::string& model)
            : Animation(actor, parent, resources)
        { setObjectRoot(model, true, false, false); }
    private:
        void addControllers() override
        {
            if (mRejectControllerRebuild)
                throw std::runtime_error("unexpected physical admission controller rebuild");
        }
    };
    struct RestoreThreads
    {
        int mPrevious = Settings::physics().mAsyncNumThreads;
        ~RestoreThreads() { Settings::physics().mAsyncNumThreads.set(mPrevious); }
    } restoreThreads;
    for (int threads : {0, 1, 2})
    {
        SCOPED_TRACE(threads);
        Settings::physics().mAsyncNumThreads.set(threads);
        NativeWorldFixture fixture;
        auto& world = fixture.mWorld;
        const auto actor = addNativeNpc(fixture, 0x900);
        const auto other = addNativeNpc(fixture, 0x901);
        const std::string model = "meshes/m15-physical-admission.nif";
        auto npc = *actor.get<ESM4::Npc>()->mBase;
        npc.mModel = "m15-physical-admission.nif";
        world.getStore().getWritable<ESM4::Npc>().insertStatic(npc, npc.mFormKey);
        ASSERT_TRUE(world.activateOblivionActor(actor));
        std::filesystem::create_directories(fixture.mDirectory / "meshes");
        {
            std::ofstream file(fixture.mDirectory / model, std::ios::binary);
            const auto bytes = nativeCarriedWeaponNif(.5f);
            file.write(bytes.data(), bytes.size());
            ASSERT_TRUE(file);
        }
        fixture.mVfs.addArchive(std::make_unique<VFS::FileSystemArchive>(fixture.mDirectory));
        fixture.mVfs.buildIndex();
        fixture.mResources.getSceneManager()->setShaderPath(
            std::filesystem::path(OPENMW_PROJECT_SOURCE_DIR) / "files/shaders");
        osg::ref_ptr<osg::Group> parent = new osg::Group;
        SourceAnimation animation(actor, parent, &fixture.mResources, model);
        SourceAnimation foreign(other, parent, &fixture.mResources, model);
        auto& physics = world.initializePhysics(new osg::Group);
        physics.addActor(actor, VFS::Path::toNormalized(model));
        const auto* movementActor = physics.getActor(actor);
        ASSERT_NE(movementActor, nullptr);
        const auto* capsuleObject = movementActor->getCollisionObject();
        const auto* capsuleProxy = capsuleObject->getBroadphaseHandle();
        ASSERT_NE(capsuleProxy, nullptr);
        const auto capsuleId = capsuleProxy->getUid();
        const auto capsuleGroup = capsuleProxy->m_collisionFilterGroup;
        const auto capsuleMask = capsuleProxy->m_collisionFilterMask;
        const auto capsulePose = capsuleObject->getWorldTransform();
        const auto capsuleFlags = capsuleObject->getCollisionFlags();
        const auto retainedMovement = [&] {
            ASSERT_EQ(physics.getActor(actor), movementActor);
            EXPECT_EQ(movementActor->getCollisionObject(), capsuleObject);
            EXPECT_FALSE(movementActor->isCollisionSuspended());
            const auto* currentProxy = capsuleObject->getBroadphaseHandle();
            ASSERT_NE(currentProxy, nullptr);
            EXPECT_EQ(currentProxy, capsuleProxy);
            EXPECT_EQ(currentProxy->getUid(), capsuleId);
            EXPECT_EQ(currentProxy->m_collisionFilterGroup, capsuleGroup);
            EXPECT_EQ(currentProxy->m_collisionFilterMask, capsuleMask);
            EXPECT_EQ(capsuleObject->getCollisionFlags(), capsuleFlags);
            EXPECT_EQ(capsuleObject->getWorldTransform(), capsulePose);
        };
        const auto capsuleRay = [&] {
            btVector3 minimum, maximum;
            capsuleObject->getCollisionShape()->getAabb(capsulePose, minimum, maximum);
            const auto center = (minimum + maximum) * .5;
            return physics.castRay({float(center.x()), float(center.y()), float(maximum.z() + 10)},
                {float(center.x()), float(center.y()), float(minimum.z() - 10)}, {}, {},
                MWPhysics::CollisionType_Actor, MWPhysics::CollisionType_World);
        };
        ASSERT_TRUE(capsuleRay().mHit);
        EXPECT_EQ(capsuleRay().mHitObject, actor);
        const auto key = actor.getCellRef().getFormKey();
        auto& combat = *world.getOblivionCombatService();
        const auto values = *combat.findActorValues(key);
        const auto life = *combat.findActorLife(key);
        const auto placement = Nif::NiTransform::getIdentity();
        const std::array<std::uint32_t, 1> filters{0x1108};
        const auto begin = [&](MWRender::Animation& renderer, std::span<const std::uint32_t> packed) {
            world.beginOblivionActorPhysicalPose(renderer, actor, placement, packed,
                MWPhysics::CollisionType_Actor, MWPhysics::CollisionType_World, nullptr);
        };
        const auto absent = [&] {
            EXPECT_FALSE(animation.hasPhysicalPose());
            EXPECT_FALSE(physics.hasActorRagdoll(actor));
            EXPECT_FALSE(physics.getActor(actor)->isCollisionSuspended());
            EXPECT_NE(physics.getActor(actor)->getCollisionObject()->getBroadphaseHandle(), nullptr);
        };
        {
            const auto source = animation.captureNativePhysicalSource(VFS::Path::toNormalized(model));
            ASSERT_TRUE(source);
            auto renderer = animation.preparePhysicalPose(*source->definition(), placement,
                MWRender::PhysicalPoseAnimation::AnimatedTargets);
            ASSERT_TRUE(renderer->isValid());
            animation.updatePtr(other);
            EXPECT_FALSE(renderer->isValid());
            EXPECT_FALSE(animation.commitPhysicalPose(*renderer));
            animation.updatePtr(actor);
            // Ptr equality alone ignores cells; a renderer moved to another
            // cell must not consume an earlier prepared ownership handoff.
            auto moved = actor;
            moved.mCell = nullptr;
            ASSERT_TRUE(actor.isInCell());
            auto cellGuard = animation.preparePhysicalPose(*source->definition(), placement);
            animation.updatePtr(moved);
            EXPECT_FALSE(cellGuard->isValid());
            EXPECT_FALSE(animation.commitPhysicalPose(*cellGuard));
            animation.updatePtr(actor);
            absent();
        }
        EXPECT_THROW(begin(foreign, filters), std::invalid_argument);
        EXPECT_THROW(begin(animation, {}), std::invalid_argument);
        absent();
        retainedMovement();
        EXPECT_FALSE(combat.actorRagdoll(key));
        // Geometry/body staging and renderer publication retain the selected
        // controllers; admission must not call a fallible rebuild hook.
        animation.mRejectControllerRebuild = true;
        begin(animation, filters);
        animation.mRejectControllerRebuild = false;
        EXPECT_TRUE(animation.hasPhysicalPose());
        EXPECT_TRUE(physics.hasActorRagdoll(actor));
        retainedMovement();
        // The native retained graph may be absent from the World while the
        // independent movement capsule remains the actual ray target.
        const auto nativeSelection = physics.captureActorRagdollWorldRegistrationSelection(actor);
        physics.setActorRagdollWorldRegistrationSelection(actor, {});
        retainedMovement();
        ASSERT_TRUE(capsuleRay().mHit);
        EXPECT_EQ(capsuleRay().mHitObject, actor);
        physics.setActorRagdollWorldRegistrationSelection(actor, nativeSelection);
        auto cached = combat.actorRagdoll(key);
        ASSERT_TRUE(cached);
        EXPECT_EQ(*cached, physics.captureActorRagdollSnapshot(actor, npc.mFormKey, model));
        EXPECT_THROW(begin(animation, filters), std::invalid_argument);
        EXPECT_EQ(combat.actorRagdoll(key), cached);
        world.endOblivionActorPhysicalPose(animation, actor);
        world.endOblivionActorPhysicalPose(animation, actor);
        absent();
        retainedMovement();
        EXPECT_FALSE(combat.actorRagdoll(key));
        // A retained pose is restored against this exact newly admitted asset.
        cached->mBodies[0].mPosition = {100, 200, 300};
        ASSERT_TRUE(combat.syncActorRagdoll(key, std::nullopt, cached));
        begin(animation, filters);
        retainedMovement();
        EXPECT_EQ(combat.actorRagdoll(key), cached);
        EXPECT_EQ(physics.captureActorRagdollSnapshot(actor, npc.mFormKey, model), *cached);
        world.endOblivionActorPhysicalPose(animation, actor);
        absent();
        retainedMovement();
        auto wrong = cached;
        wrong->mAssetHash[0] = wrong->mAssetHash[0] == 'a' ? 'b' : 'a';
        ASSERT_TRUE(combat.syncActorRagdoll(key, std::nullopt, wrong));
        // Snapshot restoration must reject before any callback detachment or
        // rebuild, not publish bodies then repair renderer ownership on failure.
        animation.mRejectControllerRebuild = true;
        EXPECT_THROW(begin(animation, filters), std::invalid_argument);
        animation.mRejectControllerRebuild = false;
        absent();
        EXPECT_EQ(combat.actorRagdoll(key), wrong);
        retainedMovement();
        ASSERT_TRUE(combat.syncActorRagdoll(key, wrong, std::nullopt));
        // Detached preparation cannot add ray targets or take the capsule.
        const auto source = animation.captureNativePhysicalSource(VFS::Path::toNormalized(model));
        ASSERT_TRUE(source);
        const auto& graph = *source->definition();
        const auto prepareNative = [&] {
            return MWWorld::PreparedNativeActorPhysicalPose::prepare(physics, animation, actor,
                graph, placement, filters, world.getOblivionPhysicalBlendConfiguration().mPostLink,
                MWPhysics::CollisionType_Actor, MWPhysics::CollisionType_World, nullptr);
        };
        {
            auto detached = prepareNative();
            ASSERT_TRUE(detached->isValid());
            EXPECT_FALSE(detached->physics().isPublished());
            const auto original = detached->captureSnapshot(npc.mFormKey, model);
            EXPECT_THROW(detached->restoreSnapshot(*wrong, npc.mFormKey, model), std::invalid_argument);
            EXPECT_EQ(detached->captureSnapshot(npc.mFormKey, model), original);
            detached->restoreSnapshot(*cached, npc.mFormKey, model);
            EXPECT_EQ(detached->captureSnapshot(npc.mFormKey, model), *cached);
            absent();
            retainedMovement();
        }
        absent();
        {
            auto admitted = prepareNative();
            auto competitor = prepareNative();
            ASSERT_TRUE(admitted->commit());
            retainedMovement();
            EXPECT_FALSE(admitted->isValid());
            EXPECT_FALSE(admitted->commit());
            EXPECT_FALSE(competitor->isValid());
            EXPECT_FALSE(competitor->commit());
            EXPECT_THROW(admitted->captureSnapshot(npc.mFormKey, model), std::invalid_argument);
            MWWorld::endNativeActorPhysicalPose(physics, animation, actor);
            retainedMovement();
            EXPECT_FALSE(competitor->isValid());
            EXPECT_FALSE(competitor->commit());
            absent();
        }
        {
            auto moved = prepareNative();
            const auto position = actor.getRefData().getPosition();
            auto changedPosition = position;
            changedPosition.pos[0] += 1;
            actor.getRefData().setPosition(changedPosition);
            EXPECT_FALSE(moved->isValid()); EXPECT_FALSE(moved->commit());
            actor.getRefData().setPosition(position);
            absent();
        }
        std::unique_ptr<MWWorld::PreparedNativeActorPhysicalPose> expiredResources;
        {
            auto temporary = std::make_unique<MWPhysics::PhysicsSystem>(&fixture.mResources, new osg::Group);
            temporary->addActor(actor, VFS::Path::toNormalized(model));
            SourceAnimation temporaryAnimation(actor, parent, &fixture.mResources, model);
            expiredResources = MWWorld::PreparedNativeActorPhysicalPose::prepare(*temporary,
                temporaryAnimation, actor, graph, placement, filters,
                world.getOblivionPhysicalBlendConfiguration().mPostLink,
                MWPhysics::CollisionType_Actor, MWPhysics::CollisionType_World, nullptr);
            ASSERT_TRUE(expiredResources->isValid());
        }
        EXPECT_FALSE(expiredResources->isValid());
        EXPECT_FALSE(expiredResources->commit());
        EXPECT_THROW(expiredResources->physics(), std::invalid_argument);
        expiredResources.reset();
        absent();
        const std::array<btTransform, 1> remotePose{
            btTransform(btQuaternion::getIdentity(), btVector3(1000, 1000, 1000))};
        const auto prepare = [&](MWPhysics::ActorRagdollCapsulePolicy policy) {
            return physics.prepareActorRagdoll(actor, graph, NifBullet::RagdollNativeLengthScale,
                remotePose, MWPhysics::CollisionType_Actor, MWPhysics::CollisionType_World, nullptr, policy);
        };
        const auto remoteRay = [&] {
            return physics.castRay({1000, 1000, 1100}, {1000, 1000, 900}, {}, {},
                MWPhysics::CollisionType_Actor, MWPhysics::CollisionType_World);
        };
        EXPECT_FALSE(remoteRay().mHit);
        {
            const auto discarded = prepare(MWPhysics::ActorRagdollCapsulePolicy::Suspend);
            EXPECT_TRUE(physics.validatePreparedActorRagdoll(*discarded));
            EXPECT_FALSE(discarded->physics().isPublished());
            EXPECT_FALSE(remoteRay().mHit);
            absent();
        }
        EXPECT_FALSE(remoteRay().mHit);
        auto retainedCapsule = prepare(MWPhysics::ActorRagdollCapsulePolicy::Retain);
        auto competing = prepare(MWPhysics::ActorRagdollCapsulePolicy::Suspend);
        MWPhysics::PhysicsSystem foreignPhysics(&fixture.mResources, new osg::Group);
        EXPECT_FALSE(foreignPhysics.validatePreparedActorRagdoll(*retainedCapsule));
        EXPECT_FALSE(foreignPhysics.commitActorRagdoll(*retainedCapsule));
        const std::array<NifBullet::RagdollNativeMotionRequest, 1> keyframed{{
            {graph.mBodies[0].mRecord, NifBullet::RagdollNativeMotion::Keyframed}}};
        retainedCapsule->physics().setNativeMotionModes(keyframed);
        EXPECT_FALSE(remoteRay().mHit);
        ASSERT_TRUE(physics.commitActorRagdoll(*retainedCapsule));
        EXPECT_FALSE(physics.validatePreparedActorRagdoll(*retainedCapsule));
        EXPECT_FALSE(physics.commitActorRagdoll(*retainedCapsule));
        EXPECT_THROW(retainedCapsule->physics(), std::invalid_argument);
        EXPECT_FALSE(physics.validatePreparedActorRagdoll(*competing));
        EXPECT_FALSE(physics.commitActorRagdoll(*competing));
        EXPECT_TRUE(physics.hasActorRagdoll(actor));
        EXPECT_FALSE(physics.getActor(actor)->isCollisionSuspended());
        EXPECT_NE(physics.getActor(actor)->getCollisionObject()->getBroadphaseHandle(), nullptr);
        EXPECT_TRUE(remoteRay().mHit);
        EXPECT_EQ(remoteRay().mHitObject, actor);
        EXPECT_EQ(physics.captureActorRagdollNativeMotionModes(actor), (std::vector(keyframed.begin(), keyframed.end())));
        const auto registration = physics.captureActorRagdollWorldRegistrationSelection(actor);
        physics.setActorRagdollWorldRegistrationSelection(actor, {});
        EXPECT_TRUE(physics.hasActorRagdoll(actor));
        EXPECT_FALSE(physics.getActor(actor)->isCollisionSuspended());
        EXPECT_NE(physics.getActor(actor)->getCollisionObject()->getBroadphaseHandle(), nullptr);
        EXPECT_FALSE(remoteRay().mHit);
        EXPECT_EQ(physics.captureActorRagdollNativeMotionModes(actor), (std::vector(keyframed.begin(), keyframed.end())));
        physics.setActorRagdollWorldRegistrationSelection(actor, registration);
        EXPECT_TRUE(remoteRay().mHit);
        physics.removeActorRagdoll(actor);
        absent();
        EXPECT_FALSE(remoteRay().mHit);
        EXPECT_FALSE(physics.validatePreparedActorRagdoll(*competing));
        EXPECT_FALSE(physics.commitActorRagdoll(*competing));
        EXPECT_THROW(competing->physics(), std::invalid_argument);
        auto changedScale = prepare(MWPhysics::ActorRagdollCapsulePolicy::Suspend);
        actor.getCellRef().setScale(2);
        EXPECT_FALSE(physics.validatePreparedActorRagdoll(*changedScale));
        EXPECT_FALSE(physics.commitActorRagdoll(*changedScale));
        EXPECT_THROW(changedScale->physics(), std::invalid_argument);
        actor.getCellRef().setScale(1);
        changedScale.reset();
        auto replacedCapsule = prepare(MWPhysics::ActorRagdollCapsulePolicy::Suspend);
        physics.remove(actor);
        physics.addActor(actor, VFS::Path::toNormalized(model));
        EXPECT_FALSE(physics.validatePreparedActorRagdoll(*replacedCapsule));
        EXPECT_FALSE(physics.commitActorRagdoll(*replacedCapsule));
        EXPECT_THROW(replacedCapsule->physics(), std::invalid_argument);
        absent();
        EXPECT_FALSE(remoteRay().mHit);
        std::unique_ptr<MWPhysics::PreparedActorRagdoll> expired;
        {
            auto temporary = std::make_unique<MWPhysics::PhysicsSystem>(&fixture.mResources, new osg::Group);
            temporary->addActor(actor, VFS::Path::toNormalized(model));
            expired = temporary->prepareActorRagdoll(actor, graph, NifBullet::RagdollNativeLengthScale,
                remotePose, MWPhysics::CollisionType_Actor, MWPhysics::CollisionType_World);
        }
        EXPECT_FALSE(expired->isValid());
        EXPECT_FALSE(expired->commit());
        EXPECT_THROW(expired->physics(), std::invalid_argument);
        expired.reset(); // Deferred geometry safely outlives its World.
        auto suspendedCapsule = prepare(MWPhysics::ActorRagdollCapsulePolicy::Suspend);
        ASSERT_TRUE(physics.commitActorRagdoll(*suspendedCapsule));
        EXPECT_TRUE(physics.getActor(actor)->isCollisionSuspended());
        EXPECT_TRUE(remoteRay().mHit);
        physics.removeActorRagdoll(actor);
        absent();
        EXPECT_FALSE(remoteRay().mHit);
        EXPECT_FALSE(combat.actorRagdoll(key));
        EXPECT_EQ(*combat.findActorValues(key), values);
        EXPECT_EQ(*combat.findActorLife(key), life);
    }
}

